from __future__ import annotations

from typing import Any, Literal, Mapping, Protocol

from pydantic import BaseModel, ConfigDict, Field

IdentityProviderType = Literal["oidc", "saml"]


class ActorContext(BaseModel):
    model_config = ConfigDict(frozen=True)

    actor_id: str
    idp_type: IdentityProviderType
    subject: str
    username: str
    display_name: str
    email: str | None = None
    group_refs: tuple[str, ...] = Field(default_factory=tuple)
    role_refs: tuple[str, ...] = Field(default_factory=tuple)
    permissions: tuple[str, ...] = Field(default_factory=tuple)
    source_claim_keys: tuple[str, ...] = Field(default_factory=tuple)


class ProtectedMutationRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")

    document_id: str
    payload: dict[str, Any] = Field(default_factory=dict)
    reason: str | None = None


class ProtectedMutationResponse(BaseModel):
    model_config = ConfigDict(frozen=True)

    status: str
    document_id: str
    actor_id: str
    write_result: dict[str, Any] = Field(default_factory=dict)


class SanitizedLogContext(BaseModel):
    model_config = ConfigDict(frozen=True)

    headers: dict[str, Any] = Field(default_factory=dict)
    claims: dict[str, Any] = Field(default_factory=dict)


class WritePort(Protocol):
    def write(
        self,
        command: ProtectedMutationRequest,
        actor: ActorContext,
    ) -> Mapping[str, Any]:
        ...


class AuditPort(Protocol):
    def record(
        self,
        event_type: str,
        actor: ActorContext,
        detail: Mapping[str, Any],
    ) -> None:
        ...

