from __future__ import annotations

import logging
import re
from typing import Any, Iterable, Mapping

from .contracts import (
    ActorContext,
    AuditPort,
    IdentityProviderType,
    ProtectedMutationRequest,
    ProtectedMutationResponse,
    SanitizedLogContext,
    WritePort,
)

_OIDC_SUBJECT_KEYS = ("sub",)
_OIDC_USERNAME_KEYS = ("preferred_username", "username", "upn", "email")
_OIDC_DISPLAY_NAME_KEYS = ("name", "display_name", "given_name")
_OIDC_EMAIL_KEYS = ("email", "upn")
_OIDC_GROUP_KEYS = ("groups", "cognito:groups", "group")
_OIDC_ROLE_KEYS = ("roles", "role")
_OIDC_PERMISSION_KEYS = ("permissions", "permission", "entitlements")
_OIDC_SCOPE_KEYS = ("scope", "scp")

_SAML_SUBJECT_KEYS = (
    "name_id",
    "NameID",
    "nameid",
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier",
)
_SAML_USERNAME_KEYS = (
    "uid",
    "username",
    "UserID",
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name",
)
_SAML_DISPLAY_NAME_KEYS = (
    "displayName",
    "display_name",
    "cn",
    "name",
)
_SAML_EMAIL_KEYS = (
    "email",
    "emailaddress",
    "mail",
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress",
)
_SAML_GROUP_KEYS = ("memberOf", "memberof", "groups", "Group")
_SAML_ROLE_KEYS = ("Role", "role", "roles")
_SAML_PERMISSION_KEYS = ("Permission", "permission", "permissions", "entitlements")

_SPLIT_PATTERN = re.compile(r"[\s,;]+")
_REDACTED = "<redacted>"


class AuthenticationRequired(PermissionError):
    """Raised when no authenticated caller context is available."""


class ClaimsNormalizationError(ValueError):
    """Raised when claims cannot be normalized into a stable actor context."""


class AuthorizationDenied(PermissionError):
    """Raised when a caller is authenticated but lacks the required permission."""

    def __init__(self, actor_id: str, required_permission: str) -> None:
        self.actor_id = actor_id
        self.required_permission = required_permission
        super().__init__(
            f"Authenticated caller {actor_id!r} lacks permission "
            f"{required_permission!r}",
        )


class TokenRedactor:
    """Redacts secrets and assertions before they reach logs."""

    def _is_sensitive_key(self, key: str) -> bool:
        lowered = key.lower().replace("-", "_")
        return (
            lowered == "authorization"
            or "token" in lowered
            or "assertion" in lowered
            or lowered.endswith("samlresponse")
        )

    def redact(self, value: Any, key: str | None = None) -> Any:
        if key is not None and self._is_sensitive_key(key):
            return _REDACTED

        if isinstance(value, Mapping):
            return {
                str(child_key): self.redact(child_value, str(child_key))
                for child_key, child_value in value.items()
            }

        if isinstance(value, (list, tuple, set, frozenset)):
            return [self.redact(item) for item in value]

        return value

    def redact_headers(self, headers: Mapping[str, Any]) -> dict[str, Any]:
        return {
            str(key).lower(): self.redact(value, str(key))
            for key, value in headers.items()
        }


class PermissionPolicy:
    """Maps external identity-provider references into internal permissions."""

    def __init__(
        self,
        external_to_internal: Mapping[str, Iterable[str]] | None = None,
    ) -> None:
        mapping = external_to_internal or {}
        self._external_to_internal = {
            self._normalize_mapping_key(key): frozenset(
                permission
                for permission in (str(item).strip() for item in values)
                if permission
            )
            for key, values in mapping.items()
        }

    def resolve(
        self,
        *,
        group_refs: Iterable[str],
        role_refs: Iterable[str],
        direct_permissions: Iterable[str],
        scopes: Iterable[str],
    ) -> tuple[str, ...]:
        resolved: set[str] = {
            permission
            for permission in (str(item).strip() for item in direct_permissions)
            if permission
        }

        for prefix, values in (
            ("groups", group_refs),
            ("roles", role_refs),
            ("permissions", direct_permissions),
            ("scopes", scopes),
        ):
            for value in values:
                resolved.update(
                    self._external_to_internal.get(
                        self._normalize_mapping_key(f"{prefix}:{value}"),
                        frozenset(),
                    ),
                )

        return tuple(sorted(resolved))

    @staticmethod
    def _normalize_mapping_key(key: str) -> str:
        return key.strip().lower()


class _ClaimView:
    def __init__(self, claims: Mapping[str, Any]) -> None:
        self._claims = {str(key): value for key, value in claims.items()}
        self._lowered = {str(key).lower(): value for key, value in claims.items()}

    def first(self, *keys: str) -> Any | None:
        for key in keys:
            if key in self._claims:
                return self._claims[key]

            lowered = key.lower()
            if lowered in self._lowered:
                return self._lowered[lowered]

        return None

    @property
    def source_claim_keys(self) -> tuple[str, ...]:
        return tuple(sorted(self._claims.keys()))


def _coerce_text(value: Any) -> str | None:
    if value is None:
        return None

    if isinstance(value, str):
        text = value.strip()
        return text or None

    text = str(value).strip()
    return text or None


def _as_values(value: Any, *, split_tokens: bool = False) -> tuple[str, ...]:
    if value is None:
        return ()

    items: list[str] = []

    if isinstance(value, str):
        candidate = value.strip()
        if not candidate:
            return ()

        if split_tokens or any(separator in candidate for separator in (",", ";", " ")):
            items.extend(token for token in _SPLIT_PATTERN.split(candidate) if token)
        else:
            items.append(candidate)
    elif isinstance(value, (list, tuple, set, frozenset)):
        for item in value:
            text = _coerce_text(item)
            if text:
                items.append(text)
    else:
        text = _coerce_text(value)
        if text:
            items.append(text)

    return tuple(sorted(set(items)))


def _compose_display_name(
    primary: Any,
    secondary_a: Any | None = None,
    secondary_b: Any | None = None,
    *,
    fallback: str,
) -> str:
    primary_text = _coerce_text(primary)
    if primary_text:
        return primary_text

    combined = " ".join(
        part
        for part in (
            _coerce_text(secondary_a),
            _coerce_text(secondary_b),
        )
        if part
    ).strip()
    if combined:
        return combined

    return fallback


class AuthSessionService:
    """Owns auth-context normalization, authorization, and audit propagation."""

    def __init__(
        self,
        *,
        permission_policy: PermissionPolicy | None = None,
        redactor: TokenRedactor | None = None,
        logger: logging.Logger | None = None,
    ) -> None:
        self._permission_policy = permission_policy or PermissionPolicy()
        self._redactor = redactor or TokenRedactor()
        self._logger = logger or logging.getLogger("backend.auth")

    def normalize_claims(
        self,
        claims: Mapping[str, Any],
        source_hint: IdentityProviderType | None = None,
    ) -> ActorContext:
        if not claims:
            raise AuthenticationRequired("No authenticated identity claims were supplied")

        view = _ClaimView(claims)
        idp_type = self._detect_source(view, source_hint)

        if idp_type == "oidc":
            subject = _coerce_text(view.first(*_OIDC_SUBJECT_KEYS))
            if not subject:
                raise ClaimsNormalizationError("OIDC claims are missing subject")

            username = (
                _coerce_text(view.first(*_OIDC_USERNAME_KEYS))
                or subject
            )
            display_name = _compose_display_name(
                view.first(*_OIDC_DISPLAY_NAME_KEYS),
                view.first("given_name"),
                view.first("family_name"),
                fallback=username,
            )
            email = _coerce_text(view.first(*_OIDC_EMAIL_KEYS))
            group_refs = _as_values(view.first(*_OIDC_GROUP_KEYS))
            role_refs = _as_values(view.first(*_OIDC_ROLE_KEYS))
            direct_permissions = _as_values(view.first(*_OIDC_PERMISSION_KEYS))
            scopes = _as_values(view.first(*_OIDC_SCOPE_KEYS), split_tokens=True)
        else:
            subject = _coerce_text(view.first(*_SAML_SUBJECT_KEYS))
            if not subject:
                raise ClaimsNormalizationError("SAML claims are missing subject")

            username = (
                _coerce_text(view.first(*_SAML_USERNAME_KEYS))
                or _coerce_text(view.first(*_SAML_EMAIL_KEYS))
                or subject
            )
            display_name = _compose_display_name(
                view.first(*_SAML_DISPLAY_NAME_KEYS),
                view.first("givenName"),
                view.first("sn"),
                fallback=username,
            )
            email = _coerce_text(view.first(*_SAML_EMAIL_KEYS))
            group_refs = _as_values(view.first(*_SAML_GROUP_KEYS))
            role_refs = _as_values(view.first(*_SAML_ROLE_KEYS))
            direct_permissions = _as_values(view.first(*_SAML_PERMISSION_KEYS))
            scopes = ()

        permissions = self._permission_policy.resolve(
            group_refs=group_refs,
            role_refs=role_refs,
            direct_permissions=direct_permissions,
            scopes=scopes,
        )

        return ActorContext(
            actor_id=f"{idp_type}:{subject}",
            idp_type=idp_type,
            subject=subject,
            username=username,
            display_name=display_name,
            email=email,
            group_refs=group_refs,
            role_refs=role_refs,
            permissions=permissions,
            source_claim_keys=view.source_claim_keys,
        )

    def require_permission(
        self,
        actor: ActorContext,
        required_permission: str,
    ) -> None:
        if required_permission not in actor.permissions:
            raise AuthorizationDenied(actor.actor_id, required_permission)

    def execute_protected_mutation(
        self,
        *,
        command: ProtectedMutationRequest,
        actor: ActorContext,
        write_port: WritePort,
        audit_port: AuditPort,
        event_type: str = "auth.protected_mutation",
    ) -> ProtectedMutationResponse:
        write_result = dict(write_port.write(command, actor))
        audit_port.record(
            event_type=event_type,
            actor=actor,
            detail={
                "document_id": command.document_id,
                "reason": command.reason,
                "payload_keys": tuple(sorted(command.payload.keys())),
                "write_result": write_result,
            },
        )
        return ProtectedMutationResponse(
            status="accepted",
            document_id=command.document_id,
            actor_id=actor.actor_id,
            write_result=write_result,
        )

    def build_log_context(
        self,
        *,
        headers: Mapping[str, Any],
        claims: Mapping[str, Any],
    ) -> SanitizedLogContext:
        return SanitizedLogContext(
            headers=self._redactor.redact_headers(headers),
            claims=self._redactor.redact(claims),
        )

    def log_access_decision(
        self,
        message: str,
        *,
        headers: Mapping[str, Any],
        claims: Mapping[str, Any],
        level: int = logging.INFO,
    ) -> None:
        sanitized = self.build_log_context(headers=headers, claims=claims)
        self._logger.log(
            level,
            message,
            extra={"auth_context": sanitized.model_dump()},
        )

    def _detect_source(
        self,
        view: _ClaimView,
        source_hint: IdentityProviderType | None,
    ) -> IdentityProviderType:
        if source_hint in ("oidc", "saml"):
            return source_hint

        if view.first(*_OIDC_SUBJECT_KEYS, *_OIDC_SCOPE_KEYS) is not None:
            return "oidc"

        if view.first(*_SAML_SUBJECT_KEYS, *_SAML_GROUP_KEYS) is not None:
            return "saml"

        raise ClaimsNormalizationError(
            "Claims do not match supported OIDC or SAML shapes",
        )

