from __future__ import annotations

import json
import sys
from pathlib import Path

import pytest
from fastapi import FastAPI
from fastapi.testclient import TestClient

sys.path.insert(0, str(Path(__file__).resolve().parents[3] / "src"))

from backend.auth.binding import build_auth_router
from backend.auth.contracts import ActorContext, ProtectedMutationRequest
from backend.auth.implementation import AuthSessionService, PermissionPolicy


class RecordingWritePort:
    def __init__(self) -> None:
        self.calls: list[dict[str, object]] = []

    def write(
        self,
        command: ProtectedMutationRequest,
        actor: ActorContext,
    ) -> dict[str, object]:
        record = {
            "document_id": command.document_id,
            "payload": dict(command.payload),
            "actor_id": actor.actor_id,
            "username": actor.username,
        }
        self.calls.append(record)
        return {
            "document_id": command.document_id,
            "persisted_by": actor.actor_id,
        }


class RecordingAuditPort:
    def __init__(self) -> None:
        self.events: list[dict[str, object]] = []

    def record(
        self,
        event_type: str,
        actor: ActorContext,
        detail: dict[str, object],
    ) -> None:
        self.events.append(
            {
                "event_type": event_type,
                "actor_id": actor.actor_id,
                "detail": detail,
            },
        )


@pytest.fixture
def permission_policy() -> PermissionPolicy:
    return PermissionPolicy(
        {
            "groups:finance-validators": {
                "documents:read",
                "documents:validate",
            },
            "groups:reviewers": {"documents:read"},
            "roles:auditor": {"audit:read"},
            "scopes:documents.write": {"documents:write"},
        },
    )


@pytest.fixture
def auth_service(permission_policy: PermissionPolicy) -> AuthSessionService:
    return AuthSessionService(permission_policy=permission_policy)


@pytest.fixture
def app_context() -> dict[str, object]:
    write_port = RecordingWritePort()
    audit_port = RecordingAuditPort()
    auth_service = AuthSessionService()

    app = FastAPI()
    app.include_router(
        build_auth_router(
            write_port=write_port,
            audit_port=audit_port,
            auth_service=auth_service,
            required_permission="documents:write",
        ),
    )

    return {
        "client": TestClient(app),
        "write_port": write_port,
        "audit_port": audit_port,
    }


def test_maps_oidc_claims_to_permission_set_deterministically(
    auth_service: AuthSessionService,
) -> None:
    actor = auth_service.normalize_claims(
        {
            "sub": "user-123",
            "preferred_username": "jane.doe",
            "name": "Jane Doe",
            "email": "jane.doe@example.com",
            "groups": ["finance-validators", "finance-validators"],
            "roles": ["auditor"],
            "permissions": ["exports:run", "documents:read"],
            "scope": "openid documents.write profile",
        },
        "oidc",
    )

    assert actor.actor_id == "oidc:user-123"
    assert actor.username == "jane.doe"
    assert actor.permissions == (
        "audit:read",
        "documents:read",
        "documents:validate",
        "documents:write",
        "exports:run",
    )


def test_maps_saml_claims_to_permission_set_deterministically(
    auth_service: AuthSessionService,
) -> None:
    actor = auth_service.normalize_claims(
        {
            "NameID": "saml-subject-456",
            "uid": "sam.reviewer",
            "displayName": "Sam Reviewer",
            "emailaddress": "sam.reviewer@example.com",
            "memberOf": ["reviewers", "finance-validators"],
            "Role": ["auditor"],
            "Permission": ["documents:read"],
        },
        "saml",
    )

    assert actor.actor_id == "saml:saml-subject-456"
    assert actor.display_name == "Sam Reviewer"
    assert actor.permissions == (
        "audit:read",
        "documents:read",
        "documents:validate",
    )


def test_get_auth_me_returns_normalized_actor_for_fixture_identity(
    app_context: dict[str, object],
) -> None:
