    response = client.get(
        "/auth/me",
        headers={
            "x-oidc-claims": json.dumps(
                {
                    "sub": "fixture-001",
                    "preferred_username": "fixture.user",
                    "name": "Fixture User",
                    "email": "fixture.user@example.com",
