def test_authorized_mutation_propagates_actor_identity_into_write_and_audit_paths(
    app_context: dict[str, object],
) -> None:
    client = app_context["client"]
    write_port = app_context["write_port"]
    audit_port = app_context["audit_port"]

    response = client.post(
        "/auth/protected-mutation",
        headers={
            "x-oidc-claims": json.dumps(
