def build_auth_router(
    *,
    write_port: WritePort,
    audit_port: AuditPort,
    auth_service: AuthSessionService | None = None,
    required_permission: str = "documents:write",
) -> APIRouter:
    service = auth_service or AuthSessionService()
    router = APIRouter()

    def current_actor(request: Request) -> ActorContext:
        claims, source = _extract_claims(request)
        if source is None:
            service.log_access_decision(
                "anonymous caller rejected",
                headers=dict(request.headers),
                claims={},
            )
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail="Authentication required",
            )

        try:
            actor = service.normalize_claims(claims, source)
        except (AuthenticationRequired, ClaimsNormalizationError) as exc:
            service.log_access_decision(
                "authentication context rejected",
                headers=dict(request.headers),
                claims=claims,
            )
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail=str(exc),
            ) from exc

        request.state.actor = actor
        return actor

    @router.get("/auth/me", response_model=ActorContext)
    def get_auth_me(actor: ActorContext = Depends(current_actor)) -> ActorContext:
        return actor

    @router.post(
        "/auth/protected-mutation",
        response_model=ProtectedMutationResponse,
    )
    def protected_mutation(
        command: ProtectedMutationRequest,
        request: Request,
        actor: ActorContext = Depends(current_actor),
    ) -> ProtectedMutationResponse:
        try:
            service.require_permission(actor, required_permission)
        except AuthorizationDenied as exc:
            service.log_access_decision(
                "authenticated caller denied by permission policy",
                headers=dict(request.headers),
                claims=getattr(request.state, "auth_claims", {}),
            )
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail=str(exc),
            ) from exc

        return service.execute_protected_mutation(
            command=command,
            actor=actor,
            write_port=write_port,
            audit_port=audit_port,
        )

    return router


def _extract_claims(
    request: Request,
) -> tuple[dict[str, Any], str | None]:
    oidc_claims_header = request.headers.get("x-oidc-claims")
    saml_claims_header = request.headers.get("x-saml-claims")

    if oidc_claims_header and saml_claims_header:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Provide either x-oidc-claims or x-saml-claims, not both",
        )

    if oidc_claims_header:
        claims = _parse_claims_header(oidc_claims_header, "x-oidc-claims")
        request.state.auth_claims = claims
        request.state.auth_source = "oidc"
        return claims, "oidc"

    if saml_claims_header:
        claims = _parse_claims_header(saml_claims_header, "x-saml-claims")
        request.state.auth_claims = claims
        request.state.auth_source = "saml"
        return claims, "saml"

    request.state.auth_claims = {}
    request.state.auth_source = None
    return {}, None


def _parse_claims_header(
    raw_value: str,
    header_name: str,
) -> dict[str, Any]:
    try:
        parsed = json.loads(raw_value)
    except json.JSONDecodeError as exc:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail=f"{header_name} must contain a JSON object",
        ) from exc

    if not isinstance(parsed, dict):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail=f"{header_name} must contain a JSON object",
        )

    return {str(key): value for key, value in parsed.items()}

