from __future__ import annotations

import json
import sys
from pathlib import Path

import pytest
from fastapi import FastAPI
from fastapi.testclient import TestClient

sys.path.insert(0, str(Path(__file__).resolve().parents[3] / "src"))

from backend.auth.binding import build_auth_router
from backend.auth.contracts import ActorContext, ProtectedMutationRequest
from backend.auth.implementation import AuthSessionService, PermissionPolicy


class RecordingWritePort:
    def __init__(self) -> None:
        self.calls: list[dict[str, object]] = []

    def write(
        self,
        command: ProtectedMutationRequest,
        actor: ActorContext,
    ) -> dict[str, object]:
        record = {
            "document_id": command.document_id,
            "payload": dict(command.payload),
            "actor_id": actor.actor_id,
            "username": actor.username,
        }
        self.calls.append(record)
        return {
            "document_id": command.document_id,
            "persisted_by": actor.actor_id,
        }


class RecordingAuditPort:
    def __init__(self) -> None:
        self.events: list[dict[str, object]] = []

    def record(
        self,
        event_type: str,
        actor: ActorContext,
        detail: dict[str, object],
    ) -> None:
        self.events.append(
            {
                "event_type": event_type,
                "actor_id": actor.actor_id,
                "detail": detail,
            },
        )


